import { useEffect, useMemo, useState, type ReactNode } from "react";
import {
  PracticeProgressPanel,
  WeekAccessGuard,
  WeekView,
  LoadingState,
  activityProgressLabel,
  completedActivityCountFromCheckedDrafts,
  isCompletableReactBlock,
  type ActivityDocument
} from "@learning-platform/ui";
import { loadPageScripts } from "../adapters/load-hub-adapters";
import { createCatalogueDraftStore } from "../catalogue/activity-draft";
import {
  CATALOGUE_PROGRESS_SCRIPTS,
  isCatalogueWeek,
  slugForCatalogueActivity
} from "../catalogue/week-activities";
import { activeContentPackage, liveContentPackage } from "../curriculum/apply-runtime";
import { weekPageFromPackage } from "../curriculum/from-package";
import { runtimeWeekForTeachingWeek } from "../curriculum/runtime-weeks";
import { createSitePath } from "../paths";
import type { PageContext } from "../page-context";
import { findRoute } from "../page-copy";
import {
  REPORT_LINK_LABEL,
  buildSessionReportUrl,
  resolveSessionNumber
} from "../reports-link";
import { PageHost } from "./PageHost";

const WEEK_TITLES: Record<number, string> = {
  1: "Introduction to Cyber Security",
  2: "Threats and Vulnerabilities",
  3: "Types of attacker",
  4: "Motivations and targets",
  5: "Impacts of cyber security incidents",
  6: "Ethical, legal and operational considerations",
  7: "Risk management, testing and monitoring"
};

function outcomeFromSubtitle(subtitle: string) {
  const match = subtitle.match(/\b(LO\d)\b/i);
  return match ? [{ id: match[1].toUpperCase(), title: match[1].toUpperCase() }] : [];
}

function progressStore(week: number) {
  return window[`Unit3Week${week}Progress` as "Unit3Week2Progress"];
}

function adjacentWeekLink(
  root: string,
  teachingWeek: number,
  livePackage: ReturnType<typeof liveContentPackage>
) {
  const record = runtimeWeekForTeachingWeek(livePackage, teachingWeek);
  if (!record?.available) return null;
  return {
    label: `Week ${teachingWeek}`,
    href: createSitePath(root, `week-${teachingWeek}/`)
  };
}

function catalogueWeekActivities(
  content: ReturnType<typeof activeContentPackage>,
  model: NonNullable<ReturnType<typeof weekPageFromPackage>>
): ActivityDocument[] {
  const ids = model.sessions.flatMap((session) => session.activities.map((item) => item.id));
  const result: ActivityDocument[] = [];
  for (const id of ids) {
    const activity = (content?.activities || []).find((entry) => entry.id === id);
    if (activity) result.push(activity as ActivityDocument);
  }
  return result;
}

export function accessibleCatalogueActivityTotal(
  content: ReturnType<typeof activeContentPackage>,
  model: NonNullable<ReturnType<typeof weekPageFromPackage>> | null
): number {
  if (!model || !content) return 0;
  return catalogueWeekActivities(content, model).filter((activity) => (
    (activity.blocks || []).some((block) => isCompletableReactBlock(block))
  )).length;
}

export function WeekPage({
  context,
  contentReady,
  adaptersReady,
  platform,
  platformState = "ready"
}: {
  context: PageContext;
  contentReady: boolean;
  adaptersReady: boolean;
  platform?: unknown;
  /** App must pass live platform state so onboarding/join cannot mass-hydrate. */
  platformState?: string;
}) {
  const route = findRoute(context);
  const week = context.week || 1;
  const weekId = `week-${week}`;
  const weekBadge = `Week ${week}: ${WEEK_TITLES[week] || ""}`.trim();
  const livePackage = contentReady ? liveContentPackage() : null;
  const content = useMemo(
    () => (contentReady ? activeContentPackage() : null),
    [contentReady]
  );
  const runtimeWeek = useMemo(
    () => runtimeWeekForTeachingWeek(livePackage, week),
    [livePackage, week]
  );
  const guardWeek = runtimeWeek || {
    id: weekId,
    teachingWeek: week,
    status: "",
    available: false,
    title: route?.heading || `Week ${week}`
  };
  const model = useMemo(
    () => (isCatalogueWeek(week) && content ? weekPageFromPackage(content, weekId) : null),
    [content, week, weekId]
  );
  const useCatalogue = Boolean(model);
  const [legacyProgress, setLegacyProgress] = useState<{ completed: number; total: number } | null>(null);
  const [practiceCompleted, setPracticeCompleted] = useState(0);
  const practiceTotal = useMemo(
    () => (useCatalogue ? accessibleCatalogueActivityTotal(content, model) : 0),
    [content, model, useCatalogue]
  );

  useEffect(() => {
    if (!adaptersReady) return;
    if (useCatalogue) {
      const scripts = CATALOGUE_PROGRESS_SCRIPTS[week] || [];
      if (scripts.length) {
        void loadPageScripts(context.root, scripts).then(() => {
          void window.Unit3BackendProgress?.reconcile?.();
        });
      }
    }
    const read = () => {
      const summary = progressStore(week)?.getCompletionSummary?.();
      if (summary) setLegacyProgress({ completed: summary.completed, total: summary.total });
    };
    read();
    window.addEventListener("unit3:backend-progress", read);
    return () => window.removeEventListener("unit3:backend-progress", read);
  }, [adaptersReady, context.root, useCatalogue, week]);

  useEffect(() => {
    if (!adaptersReady || !useCatalogue || !model || !content) {
      setPracticeCompleted(0);
      return;
    }
    // Remote mass-hydrate only when the learner identity is enrolled for this hub.
    // Auth-without-student (onboarding / join) must not fan out get_activity_state.
    const canHydrateRemote = platformState === "ready" || platformState === "no-assignments";
    if (!canHydrateRemote) {
      setPracticeCompleted(0);
      return;
    }
    let cancelled = false;
    const activities = catalogueWeekActivities(content, model);
    void Promise.all(activities.map(async (activity) => {
      try {
        const store = createCatalogueDraftStore(activity, platform as never);
        const draft = store?.hydrate ? await store.hydrate() : null;
        const checked = draft?.checked && typeof draft.checked === "object" ? draft.checked : {};
        return [activity.id, checked] as const;
      } catch {
        return [activity.id, {}] as const;
      }
    })).then((entries) => {
      if (cancelled) return;
      const checkedByActivityId = Object.fromEntries(entries);
      setPracticeCompleted(completedActivityCountFromCheckedDrafts(activities, checkedByActivityId));
    });
    return () => { cancelled = true; };
  }, [adaptersReady, content, model, platform, platformState, useCatalogue, weekId]);

  const catalogueSessions = useMemo(() => {
    if (!useCatalogue || !model || !content) return [];
    return model.sessions.map((session, sessionIndex) => {
      const count = session.activities.length;
      const packageSession = (content.sessions || []).find((entry) => entry.id === session.id);
      const sessionNumber = resolveSessionNumber({
        sessionId: session.id,
        sortOrder: (packageSession?.metadata as { sortOrder?: number } | undefined)?.sortOrder,
        index: sessionIndex
      });
      const reportHref = buildSessionReportUrl({ week, session: sessionNumber });
      return {
        id: session.id,
        title: session.title,
        kind: session.kind === "retrieval" && week === 1 ? "session" : session.kind,
        summary: session.summary,
        defaultOpen: session.defaultOpen,
        meta: `${count} ${count === 1 ? "activity" : "activities"}`,
        activities: (() => {
          const list: Array<
            | { children: ReactNode }
            | {
              id?: string;
              title: string;
              description: string;
              activityType: string;
              href: string;
              headingLevel: 3;
              actionLabel: string;
              status: string;
            }
          > = [
            {
              children: (
                <p className="unit3-session-report-link">
                  <a
                    className="lp-text-link"
                    href={reportHref}
                    data-unit3-view-report=""
                    data-week={String(week)}
                    data-session={String(sessionNumber)}
                  >
                    {REPORT_LINK_LABEL}
                  </a>
                </p>
              )
            }
          ];
          let lastGroup = "";
          for (const item of session.activities) {
            const published = (content.activities || []).find((entry) => entry.id === item.id);
            const slug = slugForCatalogueActivity(week, item.id);
            const group = String(published?.metadata?.group || "").trim();
            if (group && group !== lastGroup) {
              list.push({
                children: (
                  <h3 className="lp-session-group-label">
                    {group}
                  </h3>
                )
              });
              lastGroup = group;
            }
            list.push({
              id: item.id,
              title: item.title,
              description: published?.metadata?.summary || "",
              activityType: published?.metadata?.activityType || "Activity",
              href: createSitePath(context.root, `week-${week}/${slug}/`),
              headingLevel: 3,
              actionLabel: "Open activity",
              status: "Available"
            });
          }
          return list;
        })()
      };
    });
  }, [content, context.root, model, useCatalogue, week]);

  if (!contentReady) {
    return <LoadingState message="Loading curriculum..." />;
  }

  const panel = useCatalogue && practiceTotal > 0
    ? {
      title: `Practice progress: ${activityProgressLabel(practiceCompleted, practiceTotal)}`,
      badge: weekBadge,
      progress: practiceTotal > 0 ? practiceCompleted / practiceTotal : 0,
      completed: practiceCompleted >= practiceTotal,
      message: "Check every question in an activity to update progress. Finish activity saves your learning record. Formative practice only."
    }
    : legacyProgress
      ? {
        title: `Week ${week} progress`,
        badge: weekBadge,
        score: { correct: legacyProgress.completed, total: legacyProgress.total },
        progress: legacyProgress.total > 0 ? legacyProgress.completed / legacyProgress.total : 0,
        completed: legacyProgress.total > 0 && legacyProgress.completed >= legacyProgress.total,
        message: "Signed-in completion is confirmed by the learner service. Drafts stay in this browser until submitted."
      }
      : null;

  const weekStatus = model?.week.status || guardWeek.status || "";
  const previousWeek = adjacentWeekLink(context.root, week - 1, livePackage);
  const nextWeek = adjacentWeekLink(context.root, week + 1, livePackage);

  return (
    <WeekAccessGuard week={guardWeek}>
      <div data-lp-week-page="">
        {panel ? (
          <PracticeProgressPanel
            title={panel.title}
            badge={panel.badge}
            score={"score" in panel ? panel.score : undefined}
            progress={panel.progress}
            completed={panel.completed}
            message={panel.message}
            defaultCollapsed
          />
        ) : null}
        <WeekView
          week={{
            id: weekId,
            teachingWeek: week,
            title: route?.heading || `Week ${week}`,
            subtitle: (route?.subtitle || "").replace(/\s+/g, " ").trim(),
            status: weekStatus
          }}
          learningOutcomes={
            useCatalogue && model?.learningOutcomes.length
              ? model.learningOutcomes
              : outcomeFromSubtitle(route?.subtitle || "")
          }
          context={{
            type: "exam",
            contextType: "exam",
            heading: "Examination context",
            description: "Formative OCR Unit 3 Cyber Security learning. This is not a live examination.",
            items: [
              { label: "Qualification", value: "OCR Level 3 IT" },
              { label: "Unit", value: "Unit 3 Cyber Security" },
              { label: "Week", value: weekBadge }
            ]
          }}
          features={{
            showTitle: false,
            showAssignmentContext: false,
            showProjectContext: false,
            showExamContext: true,
            showProgress: false
          }}
          previousWeek={week > 1 && previousWeek ? previousWeek : null}
          nextWeek={week < 7 && nextWeek ? nextWeek : null}
          sessions={useCatalogue ? catalogueSessions : [
            {
              id: `${weekId}-content`,
              title: "Learning this week",
              kind: "session",
              defaultOpen: true,
              activities: [
                {
                  children: (
                    <PageHost
                      root={context.root}
                      scripts={route?.scripts || []}
                      adaptersReady={adaptersReady}
                    />
                  )
                }
              ]
            }
          ]}
        />
      </div>
    </WeekAccessGuard>
  );
}

export function weekPageOpenable(
  teachingWeek: number,
  livePackage: ReturnType<typeof liveContentPackage>
): boolean {
  return runtimeWeekForTeachingWeek(livePackage, teachingWeek)?.available === true;
}
