import { resolveActivityVersion } from "@learning-platform/core";
import { EmptyState } from "@learning-platform/ui";
import { useEffect, useMemo, useRef, useState, type KeyboardEvent } from "react";
import {
  createCatalogueDraftStore,
  submitWrittenReport,
  type CatalogueDraft
} from "../catalogue/activity-draft";
import { catalogueActivity } from "../catalogue/week-activities";
import {
  countWords,
  formatCountdown,
  isClipboardShortcut,
  knowledgeReportConfig,
  reportQuestionId
} from "../catalogue/knowledge-report";
import { activeContentPackage } from "../curriculum/apply-runtime";
import type { PageContext } from "../page-context";

type ReportPhase = "intro" | "writing" | "additional_available" | "additional" | "submitted";

type ServerTiming = {
  phase?: string;
  additionalTimeSeconds?: number;
  additionalTimeStartedAt?: string | null;
  serverNow?: string;
};

type ExpiryAction = "ready" | "submit" | "pending";

const EXPIRY_CHECK_NOTICE = "Standard time complete. Checking your report…";
const EXPIRY_SAVED_NOTICE = "Standard time complete. Your work has been saved.";
const EXPIRY_SUBMITTED_NOTICE = "Standard time complete. Your report has been saved and submitted.";
const EXPIRY_RETRY_NOTICE = "Standard time complete. We could not check your report. Check your connection, then try again.";

function serverTiming(draft: CatalogueDraft | null | undefined): ServerTiming | null {
  const value = (draft as { knowledgeReportPhase?: ServerTiming } | null | undefined)?.knowledgeReportPhase;
  return value && typeof value === "object" ? value : null;
}

function decisiveTiming(timing: ServerTiming | null): boolean {
  const phaseName = timing?.phase;
  return phaseName === "additional_available"
    || phaseName === "additional"
    || phaseName === "additional_expired"
    || phaseName === "standard_complete"
    || phaseName === "submitted";
}

function draftFromActivityRow(row: unknown): CatalogueDraft | null {
  const recordRow = Array.isArray(row) ? row[0] : row;
  if (!recordRow || typeof recordRow !== "object") return null;
  const record = recordRow as { state?: unknown; state_payload?: unknown; knowledgeReportPhase?: unknown; responses?: unknown };
  const state = record.state || record.state_payload || (record.knowledgeReportPhase || record.responses ? record : null);
  return state && typeof state === "object" ? state as CatalogueDraft : null;
}

function draftText(draft: CatalogueDraft | null | undefined, questionId: string): string {
  const value = draft?.responses?.[questionId];
  return typeof value === "string" ? value : "";
}

function blockClipboard(event: { preventDefault: () => void }) {
  event.preventDefault();
}

export function KnowledgeReportPage({
  context,
  contentReady,
  platform
}: {
  context: PageContext;
  contentReady: boolean;
  platform?: unknown;
}) {
  const activity = useMemo(() => {
    const content = contentReady ? activeContentPackage() : null;
    return content && context.activityId
      ? catalogueActivity(content, context.activityId)
      : null;
  }, [contentReady, context.activityId]);
  const config = knowledgeReportConfig(activity);
  const questionId = activity ? reportQuestionId(activity) : "";
  const learnerSignedIn = Boolean(
    (platform as { auth?: { isSignedIn?: () => boolean } } | null)?.auth?.isSignedIn?.()
  );
  const storeRef = useRef<ReturnType<typeof createCatalogueDraftStore>>(null);
  const finaliseRef = useRef(false);
  const expiryRef = useRef(false);
  const [phase, setPhase] = useState<ReportPhase>("intro");
  const [text, setText] = useState("");
  const [serverStartedAt, setServerStartedAt] = useState<string | null>(null);
  const [additionalStartedAt, setAdditionalStartedAt] = useState<string | null>(null);
  const [additionalSeconds, setAdditionalSeconds] = useState(0);
  const [now, setNow] = useState(() => Date.now());
  const [notice, setNotice] = useState("");
  const [confirming, setConfirming] = useState(false);
  const [busy, setBusy] = useState(false);
  const [ready, setReady] = useState(false);
  const [lockedRemaining, setLockedRemaining] = useState<number | null>(null);
  const [deferExpiry, setDeferExpiry] = useState(false);
  const [expiryNeedsRetry, setExpiryNeedsRetry] = useState(false);
  const textRef = useRef(text);
  const expiryRetryRef = useRef<number | null>(null);
  const serverSkewRef = useRef(0);
  textRef.current = text;

  function noteServerClock(timing: ServerTiming | null) {
    const parsed = timing?.serverNow ? Date.parse(timing.serverNow) : Number.NaN;
    if (!Number.isFinite(parsed)) return;
    serverSkewRef.current = parsed - Date.now();
    setNow(Date.now() + serverSkewRef.current);
  }

  const durationMs = (config?.durationMinutes || 0) * 60 * 1000;
  const additionalMs = (additionalSeconds || (config?.additionalTimeMinutes || 0) * 60) * 1000;
  const minWords = config?.minWords || 0;
  const words = countWords(text);
  const remainingMs = serverStartedAt
    ? new Date(serverStartedAt).getTime() + durationMs - now
    : durationMs;
  const additionalRemainingMs = additionalStartedAt
    ? new Date(additionalStartedAt).getTime() + additionalMs - now
    : additionalMs;
  const standardExpired = phase === "writing" && serverStartedAt != null && remainingMs <= 0 && !deferExpiry;
  const additionalExpired = phase === "additional" && additionalStartedAt != null && additionalRemainingMs <= 0;
  const frozen = phase === "submitted" || phase === "additional_available" || standardExpired || additionalExpired || busy;

  useEffect(() => {
    finaliseRef.current = false;
    expiryRef.current = false;
    setExpiryNeedsRetry(false);
    setPhase("intro");
    setText("");
    setServerStartedAt(null);
    setNotice("");
    setConfirming(false);
    setReady(false);
    if (!activity) {
      storeRef.current = null;
      setReady(true);
      return;
    }
    const store = createCatalogueDraftStore(activity, platform as never);
    storeRef.current = store;
    let cancelled = false;
    (async () => {
      const hydrated = store ? await store.hydrate?.() : null;
      if (cancelled) return;
      const timing = serverTiming(hydrated);
      noteServerClock(timing);
      if (hydrated?.submission?.status === "submitted" || hydrated?.completed || timing?.phase === "submitted") {
        setText(draftText(hydrated, questionId));
        setPhase("submitted");
        setLockedRemaining(0);
        setNotice("Your report has been submitted.");
      } else if (timing?.phase === "additional" && timing.additionalTimeStartedAt) {
        setText(draftText(hydrated, questionId));
        setServerStartedAt(hydrated?.startedAt || null);
        setAdditionalStartedAt(timing.additionalTimeStartedAt);
        setAdditionalSeconds(Number(timing.additionalTimeSeconds) || 0);
        setPhase("additional");
      } else if (timing?.phase === "additional_available") {
        setText(draftText(hydrated, questionId));
        setServerStartedAt(hydrated?.startedAt || null);
        setPhase("additional_available");
        setNotice("Standard time complete. Your work has been saved.");
      } else if (timing?.phase === "additional_expired" && timing.additionalTimeStartedAt) {
        setText(draftText(hydrated, questionId));
        setServerStartedAt(hydrated?.startedAt || null);
        setAdditionalStartedAt(timing.additionalTimeStartedAt);
        setAdditionalSeconds(Number(timing.additionalTimeSeconds) || 0);
        setPhase("additional");
      } else if (timing?.phase === "standard_complete") {
        setText(draftText(hydrated, questionId));
        setServerStartedAt(hydrated?.startedAt || null);
        setPhase("writing");
      } else if (hydrated?.startedAt) {
        setText(draftText(hydrated, questionId));
        setServerStartedAt(hydrated.startedAt);
        setPhase("writing");
      } else {
        setText(draftText(hydrated, questionId));
      }
      setReady(true);
    })();
    return () => {
      cancelled = true;
      if (expiryRetryRef.current != null) {
        window.clearTimeout(expiryRetryRef.current);
        expiryRetryRef.current = null;
      }
    };
  }, [activity, platform, questionId, learnerSignedIn]);

  useEffect(() => {
    if ((phase !== "writing" && phase !== "additional") || !serverStartedAt) return undefined;
    const timer = window.setInterval(() => setNow(Date.now() + serverSkewRef.current), 250);
    return () => window.clearInterval(timer);
  }, [phase, serverStartedAt]);

  useEffect(() => {
    if ((phase !== "writing" && phase !== "additional") || frozen) return;
    const store = storeRef.current;
    if (!store || !questionId) return;
    store.save?.({
      responses: { [questionId]: text },
      checked: {},
      results: {}
    });
  }, [text, phase, frozen, questionId]);

  async function acceptedText(): Promise<string> {
    const store = storeRef.current;
    const saved = await store?.flush?.();
    const fromServer = draftText(saved?.state, questionId);
    if (saved?.state && questionId in (saved.state.responses || {})) {
      setText(fromServer);
      return fromServer;
    }
    return text;
  }

  async function finalise(becauseExpired: boolean) {
    if (!activity || !config || finaliseRef.current) return;
    finaliseRef.current = true;
    setBusy(true);
    setConfirming(false);
    storeRef.current?.save?.({
      responses: { [questionId]: textRef.current },
      checked: {},
      results: {}
    });
    const latest = await acceptedText();
    const result = await submitWrittenReport(activity, questionId, latest, platform as never, minWords);
    setBusy(false);
    if (result.status === "submitted" || result.code === "TIMED_REPORT_ALREADY_SUBMITTED") {
      setLockedRemaining(becauseExpired ? 0 : Math.max(0, remainingMs));
      setPhase("submitted");
      setExpiryNeedsRetry(false);
      setNotice(becauseExpired
        ? (phase === "additional"
          ? "Additional time is complete. Your report has been saved and submitted."
          : EXPIRY_SUBMITTED_NOTICE)
        : "Your report has been submitted.");
      return;
    }
    finaliseRef.current = false;
    if (becauseExpired && result.code === "ADDITIONAL_TIME_NOT_STARTED") {
      const recovered = await readAuthoritativeExpiry();
      if (showAuthoritativeExpiry(recovered.draft, recovered.timing) === "ready") return;
    }
    if (becauseExpired && result.code === "MINIMUM_WORDS_NOT_MET") {
      setDeferExpiry(true);
      if (expiryRetryRef.current != null) window.clearTimeout(expiryRetryRef.current);
      expiryRetryRef.current = window.setTimeout(() => {
        expiryRetryRef.current = null;
        setDeferExpiry(false);
      }, 15000);
      setNotice("Keep writing until the time is up or you reach the minimum word count.");
      return;
    }
    if (becauseExpired) {
      expiryRef.current = false;
      setExpiryNeedsRetry(true);
      setNotice(EXPIRY_RETRY_NOTICE);
      return;
    }
    setNotice(result.reason || "Your report is still saved on this device. It has not been sent to your learning record yet.");
  }

  function showAuthoritativeExpiry(draft: CatalogueDraft | null, timing: ServerTiming | null): ExpiryAction {
    const serverText = draftText(draft, questionId);
    if (serverText) setText(serverText);
    if (timing?.phase === "submitted") {
      setLockedRemaining(0);
      setPhase("submitted");
      setExpiryNeedsRetry(false);
      setNotice(EXPIRY_SUBMITTED_NOTICE);
      return "ready";
    }
    if (timing?.phase === "additional_available") {
      setPhase("additional_available");
      setExpiryNeedsRetry(false);
      setNotice(EXPIRY_SAVED_NOTICE);
      return "ready";
    }
    if (timing?.phase === "additional" && timing.additionalTimeStartedAt) {
      setAdditionalStartedAt(timing.additionalTimeStartedAt);
      setAdditionalSeconds(Number(timing.additionalTimeSeconds) || 0);
      setPhase("additional");
      setExpiryNeedsRetry(false);
      setNotice("");
      return "ready";
    }
    if (timing?.phase === "standard_complete" || timing?.phase === "additional_expired") {
      return "submit";
    }
    return "pending";
  }

  async function readAuthoritativeExpiry(): Promise<{ draft: CatalogueDraft | null; timing: ServerTiming | null }> {
    const store = storeRef.current;
    store?.save?.({
      responses: { [questionId]: textRef.current },
      checked: {},
      results: {}
    });
    const progress = (platform as {
      progress?: { getActivityState?: (activityKey: string, activityVersion: string) => Promise<unknown> };
    } | null)?.progress;
    const freshHydrate = store as {
      hydrate?: (local?: unknown, options?: { fresh?: boolean }) => Promise<CatalogueDraft | null>;
    } | null;
    let latestDraft: CatalogueDraft | null = null;
    let latestTiming: ServerTiming | null = null;
    for (let attempt = 0; attempt < 4; attempt += 1) {
      if (attempt > 0) await new Promise((resolve) => window.setTimeout(resolve, 200));
      const flushed = await store?.flush?.();
      const flushedDraft = (flushed?.state as CatalogueDraft | undefined) || null;
      const flushedTiming = serverTiming(flushedDraft);
      if (flushedDraft) latestDraft = flushedDraft;
      if (flushedTiming) latestTiming = flushedTiming;
      if (decisiveTiming(flushedTiming)) return { draft: flushedDraft, timing: flushedTiming };
      // A null flush means a save is already in flight or the draft is already clean.
      // Wait for that save before reading, so the server freezes the latest accepted draft.
      if (!flushed && attempt < 3) continue;
      if (activity && progress?.getActivityState) {
        const row = await progress.getActivityState(activity.id, resolveActivityVersion(activity));
        const draft = draftFromActivityRow(row);
        const timing = serverTiming(draft);
        if (draft) latestDraft = draft;
        if (timing) latestTiming = timing;
        if (decisiveTiming(timing)) return { draft, timing };
      }
      const hydrated = await freshHydrate?.hydrate?.(undefined, { fresh: true });
      const timing = serverTiming(hydrated);
      if (hydrated) latestDraft = hydrated;
      if (timing) latestTiming = timing;
      if (decisiveTiming(timing)) return { draft: hydrated, timing };
    }
    return { draft: latestDraft, timing: latestTiming };
  }

  async function reconcileStandardExpiry() {
    if (expiryRef.current) return;
    expiryRef.current = true;
    setExpiryNeedsRetry(false);
    setBusy(true);
    setNotice(EXPIRY_CHECK_NOTICE);
    try {
      const recovered = await readAuthoritativeExpiry();
      const action = showAuthoritativeExpiry(recovered.draft, recovered.timing);
      if (action === "submit") {
        await finalise(true);
        return;
      }
      if (action === "pending") {
        expiryRef.current = false;
        setExpiryNeedsRetry(true);
        setNotice(EXPIRY_RETRY_NOTICE);
      }
    } catch {
      expiryRef.current = false;
      setExpiryNeedsRetry(true);
      setNotice(EXPIRY_RETRY_NOTICE);
    } finally {
      setBusy(false);
    }
  }

  useEffect(() => {
    if ((phase !== "writing" && phase !== "additional") || !ready || !activity || standardExpired || additionalExpired) return undefined;
    let cancelled = false;
    const readServerClock = async () => {
      const progress = (platform as {
        progress?: { getActivityState?: (activityKey: string, activityVersion: string) => Promise<unknown> };
      } | null)?.progress;
      if (!progress?.getActivityState) return;
      try {
        const row = await progress.getActivityState(activity.id, resolveActivityVersion(activity));
        if (cancelled) return;
        noteServerClock(serverTiming(draftFromActivityRow(row)));
      } catch {
        // The expiry reconciliation reports a real failure if the sitting cannot be read.
      }
    };
    const timer = window.setInterval(() => { void readServerClock(); }, 2000);
    void readServerClock();
    return () => {
      cancelled = true;
      window.clearInterval(timer);
    };
  }, [activity, additionalExpired, phase, platform, ready, standardExpired]);

  useEffect(() => {
    if (phase !== "writing" || !standardExpired || !ready) return;
    void reconcileStandardExpiry();
    // The ref blocks a second expiry pass while reconciliation or submission is running.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [standardExpired, phase, ready]);

  useEffect(() => {
    if (phase !== "additional" || !additionalExpired || !ready) return;
    void finalise(true);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [additionalExpired, phase, ready]);

  async function startTask() {
    if (!activity || !questionId || busy) return;
    setBusy(true);
    setNotice("");
    const store = storeRef.current;
    store?.save?.({
      responses: { [questionId]: text },
      checked: {},
      results: {}
    });
    const saved = await store?.flush?.();
    const startedAt = saved?.startedAt || null;
    setBusy(false);
    if (!startedAt) {
      setNotice("The timer could not be started. Check that you are signed in, then try again.");
      return;
    }
    setServerStartedAt(startedAt);
    setNow(Date.now());
    setPhase("writing");
  }

  async function continueAdditional() {
    if (!activity || busy) return;
    setBusy(true);
    setNotice("");
    const starter = (platform as {
      knowledgeReport?: { startAdditionalTime?: (activityKey: string, activityVersion: string) => Promise<{ state?: CatalogueDraft; startedAt?: string } | null> };
    } | null)?.knowledgeReport?.startAdditionalTime;
    if (!starter) {
      setBusy(false);
      setNotice("Additional time could not be started. Check that you are signed in, then try again.");
      return;
    }
    try {
      const saved = await starter(activity.id, resolveActivityVersion(activity));
      const timing = serverTiming(draftFromActivityRow(saved));
      if (!timing?.additionalTimeStartedAt) {
        setNotice("Additional time could not be started. Check that you are signed in, then try again.");
        return;
      }
      noteServerClock(timing);
      setAdditionalStartedAt(timing.additionalTimeStartedAt);
      setAdditionalSeconds(Number(timing.additionalTimeSeconds) || (config?.additionalTimeMinutes || 0) * 60);
      setPhase("additional");
      setNotice("");
    } catch {
      setNotice("Additional time could not be started. Check that you are signed in, then try again.");
    }
    setBusy(false);
  }

  function onEditorKeyDown(event: KeyboardEvent<HTMLTextAreaElement>) {
    if (frozen) return;
    if (isClipboardShortcut(event)) event.preventDefault();
  }

  if (!contentReady || !ready) return null;
  if (!activity || !config) {
    return (
      <EmptyState
        heading="Knowledge Report"
        message="This knowledge report is not available."
      />
    );
  }

  const title = activity.metadata?.title || "Knowledge Report";
  const minimumMet = words >= minWords;

  return (
    <article className="knowledge-report" aria-labelledby="knowledge-report-title">
      <header className="knowledge-report__header">
        <h2 id="knowledge-report-title">{title}</h2>
        {phase === "intro" ? (
          <>
            {config.brief ? <p>{config.brief}</p> : null}
            <p>Time allowed: {config.durationMinutes} minutes</p>
            <p>Minimum expected word count: {config.minWords} words</p>
            <button className="lp-button" type="button" onClick={() => { void startTask(); }} disabled={busy}>
              Start Task
            </button>
          </>
        ) : (
          <div className="knowledge-report__status">
            <p className="knowledge-report__timer" role="timer">
              <span className="visually-hidden">{phase === "additional" ? "Additional time remaining " : "Time remaining "}</span>
              {phase === "additional" ? `Additional time: ${formatCountdown(additionalRemainingMs)}` : formatCountdown(phase === "submitted" ? (lockedRemaining ?? 0) : remainingMs)}
            </p>
            <p id="knowledge-report-word-count">
              {minimumMet
                ? `Word count: ${words} ✓ Minimum reached`
                : `Word count: ${words} / ${minWords} minimum`}
            </p>
          </div>
        )}
      </header>

      {phase !== "intro" ? (
        <div className="knowledge-report__layout">
          <div className="knowledge-report__editor">
            <label className="visually-hidden" htmlFor="knowledge-report-text">Your report</label>
            <textarea
              id="knowledge-report-text"
              className="knowledge-report__textarea"
              value={text}
              onChange={(event) => setText(event.target.value)}
              onKeyDown={onEditorKeyDown}
              onCopy={blockClipboard}
              onCut={blockClipboard}
              onPaste={blockClipboard}
              onDrop={blockClipboard}
              readOnly={frozen}
              spellCheck
              aria-describedby="knowledge-report-word-count"
              data-academic-integrity="exclude"
            />
            {phase === "writing" && standardExpired ? (
              <div>
                <p>Standard time complete</p>
                {expiryNeedsRetry ? (
                  <button className="lp-button" type="button" onClick={() => { void reconcileStandardExpiry(); }}>
                    Try again
                  </button>
                ) : (
                  <p>Checking your report…</p>
                )}
              </div>
            ) : null}
            {phase === "additional_available" ? (
              <div>
                <p>Standard time complete</p>
                <p>Your work has been saved.</p>
                <p>Additional time available: {config.additionalTimeMinutes || Math.round(additionalSeconds / 60)} minutes</p>
                <button className="lp-button" type="button" onClick={() => { void continueAdditional(); }} disabled={busy}>
                  Continue with additional time
                </button>
              </div>
            ) : null}
            {phase === "writing" && !minimumMet ? (
              <p id="knowledge-report-minimum">Minimum {minWords} words required before you can submit.</p>
            ) : null}
            {confirming ? (
              <div role="group" aria-labelledby="knowledge-report-confirm-heading">
                <p id="knowledge-report-confirm-heading">
                  Submit this report? You will not be able to change it after you submit.
                </p>
                <button className="lp-button" type="button" onClick={() => { void finalise(false); }} disabled={busy}>
                  Submit Report
                </button>
                <button className="lp-button lp-button--secondary" type="button" onClick={() => setConfirming(false)}>
                  Keep writing
                </button>
              </div>
            ) : (
              <button
                className="lp-button"
                type="button"
                disabled={(phase !== "writing" && phase !== "additional") || !minimumMet || busy || standardExpired || additionalExpired}
                aria-describedby={minimumMet ? undefined : "knowledge-report-minimum"}
                onClick={() => setConfirming(true)}
              >
                Submit Report
              </button>
            )}
            {notice ? (
              <p role="status">{notice}</p>
            ) : null}
          </div>
          <aside className="knowledge-report__guidance" aria-labelledby="knowledge-report-guidance-heading">
            <h3 id="knowledge-report-guidance-heading">Guidance</h3>
            {config.guidance.map((section) => (
              <section key={section.heading}>
                <h4>{section.heading}</h4>
                <ul>
                  {(section.prompts || []).map((prompt) => (
                    <li key={prompt}>{prompt}</li>
                  ))}
                </ul>
              </section>
            ))}
            {config.sentenceStarters.length ? (
              <section>
                <h4>Sentence starters</h4>
                <ul>
                  {config.sentenceStarters.map((starter) => (
                    <li key={starter}>{starter}</li>
                  ))}
                </ul>
              </section>
            ) : null}
          </aside>
        </div>
      ) : null}
      {phase === "intro" && notice ? <p role="status">{notice}</p> : null}
    </article>
  );
}
